def is_holiday(date: str) -> bool:
    """True if date is a company holiday per calendars/company_2025.ics."""
    # Parse the input date string
    try:
        target = datetime.datetime.strptime(date, "%Y-%m-%d").date()
    except ValueError:
        return False
    # Path to the iCal file
    ics_path = os.path.join("calendars", "company_2025.ics")
    if not os.path.isfile(ics_path):
        return False
    # Read and parse events
    with open(ics_path, "r", encoding="utf-8") as f:
        lines = f.readlines()
    events = []
    curr = {}
    for line in lines:
        line = line.strip()
        if line == "BEGIN:VEVENT":
            curr = {}
        elif line == "END:VEVENT":
            events.append(curr)
        else:
            if ":" in line:
                key, val = line.split(":", 1)
                curr[key] = val
    # Check each event for date overlap
    for ev in events:
        # DTSTART and DTEND may be full datetime or date
        def parse_dt(val):
            try:
                # datetime with T
                return datetime.datetime.strptime(val, "%Y%m%dT%H%M%SZ").date()
            except ValueError:
                try:
                    return datetime.datetime.strptime(val, "%Y%m%d").date()
                except ValueError:
                    return None
        start = parse_dt(ev.get("DTSTART", ""))
        end = parse_dt(ev.get("DTEND", ""))
        if start is None:
            continue
        # If end missing, treat as single day
        if end is None:
            end = start
        # Inclusive range
        if start <= target <= end:
            return True
    return False

